{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Levofloxacin, a close fluoroquinolone analogue sharing the 4-quinolone-3-carboxylic acid core, fluorine, and basic amine, has an absolute oral bioavailability of approximately 99% in healthy volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Trovafloxacin, another fluoroquinolone with a basic amine and carboxylic acid, showed mean absolute oral bioavailability of 87.6% in healthy volunteers, confirming that this chemotype achieves F well above 20% despite ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Antofloxacin, a close fluoroquinolone analogue, is reported to have high oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Cilomilast, a carboxylic-acid-containing drug with complete oral bioavailability (mean 96% absolute in healthy volunteers), demonstrates that an ionized carboxylic acid does not preclude F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Dolutegravir (S/GSK1349572), a quinolone-type carboxylic acid with good oral bioavailability in humans, provides additional support for high F in this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human absolute bioavailability studies on close fluoroquinolone analogues (levofloxacin ~99%, trovafloxacin ~88%, antofloxacin high) and other carboxylic-acid drugs (cilomilast ~96%, dolutegravir good) consistently support F >= 20%. The unfavorable physicochemical prior is outweighed by direct experimental evidence from structurally relevant molecules.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No human PK data for the exact piperidine substituent containing the exocyclic fluoromethylidene-aminomethyl group.",
    "Potential impact of the unusual substituent on transporter-mediated absorption or first-pass metabolism is uncharacterized.",
    "No food-effect or dose-proportionality data for the query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C47", "C51", "C02", "C37", "C53"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "fluoroquinolone/quinolone oral bioavailability"
    }
  ],
  "revision_action": "initial"
}

